<?php declare(strict_types=1);$reportSource=$reportUi['source'];?>
<section class="card" data-activity-report-list><h2><?=e($reportText('Berichte dieser Art'))?></h2><form method="get" class="report-filter"><?=hidden('view','documents').hidden('tab','activity-reports').hidden('report_kind',$reportKind)?><label><?=e($reportText('Jahr oder Zeitraum suchen'))?><input class="form-control" type="search" name="q" maxlength="150" value="<?=e($reportSource['q'])?>"></label><label><?=e($reportText('Status'))?><select class="form-control" name="state"><?php foreach([''=>'Alle','review'=>'Zur Prüfung','approved'=>'Freigabe gespeichert']as$value=>$label):?><option value="<?=e($value)?>" <?=$reportSource['state']===$value?'selected':''?>><?=e($reportText($label))?></option><?php endforeach?></select></label><button class="btn btn-outline theme-secondary"><?=e($reportText('Anzeigen'))?></button></form><p><?=e($reportText('{count} Berichte · Seite {page} / {pages}',['count'=>$reportUi['total'],'page'=>$reportUi['page'],'pages'=>$reportUi['pages']]))?></p>
<?php foreach($reportUi['rows']as$item):?><a class="report-row" href="<?=e($reportUrl(['report_id'=>$item['id']]))?>"><strong><?=e($item['from_year'].($item['from_year']!==$item['to_year']?' - '.$item['to_year']:''))?></strong><span><?=e($reportText($item['state']==='approved'?'Freigabe gespeichert':'Zur Prüfung'))?></span></a><?php endforeach?>
<?php if($reportUi['rows']===[]):?><p><?=e($reportText('Keine passenden Tätigkeitsberichte.'))?></p><?php endif?>
<?php if($reportUi['pages']>1):?><nav class="actions report-pages" aria-label="<?=e($reportText('Berichtsseiten'))?>"><?php if($reportUi['page']>1):?><a class="btn btn-outline theme-secondary" href="<?=e($reportUrl(['q'=>$reportSource['q'],'state'=>$reportSource['state'],'page'=>(string)($reportUi['page']-1)]))?>"><?=e($reportText('Vorherige Seite'))?></a><?php endif?><?php if($reportUi['page']<$reportUi['pages']):?><a class="btn btn-outline theme-secondary" href="<?=e($reportUrl(['q'=>$reportSource['q'],'state'=>$reportSource['state'],'page'=>(string)($reportUi['page']+1)]))?>"><?=e($reportText('Nächste Seite'))?></a><?php endif?><form method="get"><?=hidden('view','documents').hidden('tab','activity-reports').hidden('report_kind',$reportKind).hidden('q',$reportSource['q']).hidden('state',$reportSource['state'])?><label><?=e($reportText('Seite wählen'))?><input class="form-control" type="number" name="page" min="1" max="<?=$reportUi['pages']?>" value="<?=$reportUi['page']?>" required></label><button class="btn btn-outline theme-secondary"><?=e($reportText('Seite öffnen'))?></button></form></nav><?php endif?></section>
